"use client";

import { useState, useSyncExternalStore } from "react";
// Generated by scripts/export-ai-usage.mjs (runs on every commit). Daily AI token totals.
import usage from "../data/ai-usage.json";

interface DayUsage {
  input: number;
  output: number;
  cacheWrite: number;
  cacheRead: number;
}

const CHART_DAYS = 30;

const days = usage.days as Record<string, DayUsage>;
const dayTotal = (d: DayUsage) => d.input + d.output + d.cacheWrite + d.cacheRead;

const compact = new Intl.NumberFormat("en", { notation: "compact", maximumFractionDigits: 1 });
const longDate = new Intl.DateTimeFormat("en", { day: "numeric", month: "short", year: "numeric", timeZone: "UTC" });
const shortDate = new Intl.DateTimeFormat("en", { day: "numeric", month: "short", timeZone: "UTC" });

const pad = (n: number) => String(n).padStart(2, "0");
const toKey = (d: Date) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const fromKey = (key: string) => {
  const [y, m, d] = key.split("-").map(Number);
  return new Date(y, m - 1, d);
};
const asUtc = (key: string) => new Date(`${key}T00:00:00Z`);

const noopSubscribe = () => () => {};

const sortedKeys = Object.keys(days).sort();
const firstDay = sortedKeys[0];
const lastDay = sortedKeys[sortedKeys.length - 1];

const totals = Object.values(days).reduce(
  (sum, d) => ({
    input: sum.input + d.input,
    output: sum.output + d.output,
    cacheWrite: sum.cacheWrite + d.cacheWrite,
    cacheRead: sum.cacheRead + d.cacheRead,
  }),
  { input: 0, output: 0, cacheWrite: 0, cacheRead: 0 }
);

/** The last CHART_DAYS days ending on `endKey`, with 0 for days without usage. */
function buildBars(endKey: string) {
  const end = fromKey(endKey);
  return Array.from({ length: CHART_DAYS }, (_, i) => {
    const d = new Date(end);
    d.setDate(d.getDate() - (CHART_DAYS - 1 - i));
    const key = toKey(d);
    return { date: key, count: days[key] ? dayTotal(days[key]) : 0 };
  });
}

/** Rounds up to a clean axis maximum: 1, 2 or 5 times a power of ten. */
function niceMax(value: number) {
  if (value <= 0) return 1;
  const power = 10 ** Math.floor(Math.log10(value));
  return ([1, 2, 5, 10].find((step) => step * power >= value) ?? 10) * power;
}

export default function TokenStats() {
  // The page is pre-rendered at build time, so "today" is only known in the browser.
  // The server render ends at the last exported day; the browser then extends it to today.
  const today = useSyncExternalStore(noopSubscribe, () => toKey(new Date()), () => lastDay);
  const [hovered, setHovered] = useState<number | null>(null);

  if (!firstDay) return null;

  const endKey = today > lastDay ? today : lastDay;
  const bars = buildBars(endKey);
  const periodTotal = bars.reduce((sum, bar) => sum + bar.count, 0);
  const max = niceMax(Math.max(...bars.map((bar) => bar.count)));
  const ticks = [max, max / 2, 0];

  const breakdown = [
    { label: "Input", value: totals.input },
    { label: "Output", value: totals.output },
    { label: "Cache write", value: totals.cacheWrite },
    { label: "Cache read", value: totals.cacheRead },
  ];

  return (
    <>
      <div className="hud-panel flex flex-col gap-6 p-6 md:flex-row md:items-end md:justify-between">
        <div>
          <p className="text-5xl font-bold text-accent">{compact.format(dayTotal(totals))}</p>
          <p className="mt-1 text-sm text-zinc-400">Total AI tokens</p>
          <p className="mt-1 text-xs text-zinc-500">
            Since {longDate.format(asUtc(firstDay))} · updated {longDate.format(asUtc(usage.updatedAt.slice(0, 10)))}
          </p>
        </div>
        <dl className="grid grid-cols-2 gap-x-8 gap-y-3 sm:grid-cols-4">
          {breakdown.map((item) => (
            <div key={item.label}>
              <dt className="text-xs text-zinc-500">{item.label}</dt>
              <dd className="text-lg font-bold text-white">{compact.format(item.value)}</dd>
            </div>
          ))}
        </dl>
      </div>

      <div className="hud-panel mt-4 p-6">
        <p className="mb-4 text-sm text-zinc-300">
          <span className="text-accent">{compact.format(periodTotal)}</span> AI tokens in the last {CHART_DAYS} days
        </p>

        <div className="flex gap-3">
          {/* Y axis: clean compact ticks, recessive */}
          <div className="flex h-40 flex-col justify-between text-right text-[10px] leading-none text-zinc-500">
            {ticks.map((tick) => (
              <span key={tick} className="-translate-y-1/2 first:translate-y-0 last:translate-y-0">
                {compact.format(tick)}
              </span>
            ))}
          </div>

          <div className="relative flex-1">
            {/* Gridlines at each tick */}
            <div className="pointer-events-none absolute inset-x-0 top-0 flex h-40 flex-col justify-between">
              {ticks.map((tick) => (
                <span key={tick} className={`h-px ${tick === 0 ? "bg-white/20" : "bg-white/[0.06]"}`} />
              ))}
            </div>

            {/* Bars: each column is a full-height hover target; the bar is capped at 24px wide */}
            <div className="relative flex h-40 items-end" onMouseLeave={() => setHovered(null)}>
              {bars.map((bar, i) => (
                <div
                  key={bar.date}
                  className="flex h-full flex-1 items-end justify-center px-px"
                  onMouseEnter={() => setHovered(i)}
                >
                  <span
                    className={`block w-full max-w-6 rounded-t-[4px] transition-colors ${
                      hovered === i ? "bg-white" : "bg-accent"
                    }`}
                    style={{ height: `${(bar.count / max) * 100}%` }}
                  />
                </div>
              ))}

              {hovered !== null && (
                // Centered on the bar, but pinned to the chart's edge near either end so it never overflows.
                <div
                  className={`pointer-events-none absolute bottom-full mb-2 whitespace-nowrap border border-white/10 bg-black/90 px-2.5 py-1.5 text-xs ${
                    hovered < CHART_DAYS * 0.25 ? "" : hovered > CHART_DAYS * 0.75 ? "-translate-x-full" : "-translate-x-1/2"
                  }`}
                  style={{
                    left: `${
                      hovered < CHART_DAYS * 0.25
                        ? (hovered / CHART_DAYS) * 100
                        : hovered > CHART_DAYS * 0.75
                          ? ((hovered + 1) / CHART_DAYS) * 100
                          : ((hovered + 0.5) / CHART_DAYS) * 100
                    }%`,
                  }}
                >
                  <span className="text-white">{compact.format(bars[hovered].count)} tokens</span>
                  <span className="ml-2 text-zinc-500">{shortDate.format(asUtc(bars[hovered].date))}</span>
                </div>
              )}
            </div>

            {/* X axis: first, middle and last day */}
            <div className="mt-2 flex justify-between text-[10px] text-zinc-500">
              {[0, Math.floor(CHART_DAYS / 2), CHART_DAYS - 1].map((i) => (
                <span key={i}>{shortDate.format(asUtc(bars[i].date))}</span>
              ))}
            </div>
          </div>
        </div>

        {/* Table view for screen readers */}
        <table className="sr-only">
          <caption>Daily AI tokens, last {CHART_DAYS} days</caption>
          <thead>
            <tr>
              <th>Date</th>
              <th>Tokens</th>
            </tr>
          </thead>
          <tbody>
            {bars.map((bar) => (
              <tr key={bar.date}>
                <td>{bar.date}</td>
                <td>{bar.count}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </>
  );
}
